content.content:
14	
15	
16	.modules-left,
17	.modules-center,
18	.modules-right{
19	    background: @primary-container;
20	    border: 2px solid @outline;
21	    border-radius: 10px;
22	    /* 4px, not 6px: the 26px sprites need the vertical room, and this keeps the
23	       bar at 56px — the height it already rendered at before the sprites moved
24	       into CSS. Raising it to 6px forces the bar to 60px. */
25	    margin: 4px 4px;
26	    padding: 4px 12px;
27	}
28	
29	/* Every workspace button reserves the exact box the active one uses — same
30	   padding, margin, min size, and a same-width *transparent* border. Without
31	   this, only the active button carries a 1px border, so it is taller than the
32	   inactive buttons; the bar height tracks its tallest child, so the whole bar
33	   jumps up and down as the pokeball (active button) appears/moves. Reserving
34	   the border space up front keeps every button one fixed height.
35	   :not(.taskbar) keeps this off the taskbar module's buttons. */
36	#workspaces:not(.taskbar) button {
37	    padding: 4px 4px;
38	    margin: 4px 0px;
39	    min-width: 20px;
40	    min-height: 20px;
41	    border: 1px solid transparent;
42	    border-radius: 10px;
43	}
44	
45	/* :not(.taskbar) keeps this off the taskbar module's active button */
46	#workspaces:not(.taskbar) button.active {
47	    background-image: url('/home/krubics/.config/waybar/assets/pokeball.png');
48	    background-position: center;
49	    background-repeat: no-repeat;
50	    background-size: contain;
51	    background-origin: content-box; /* inset the ball from the accent pill's edges */
52	    background-color: @primary;
53	    color: transparent; /* hides the workspace number behind the pokeball */

